PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS projects (id TEXT PRIMARY KEY,owner_id TEXT NOT NULL,name TEXT NOT NULL,goal_text TEXT NOT NULL,time_constraint_text TEXT NOT NULL,timezone TEXT NOT NULL,goal_version INTEGER NOT NULL DEFAULT 1,revision INTEGER NOT NULL DEFAULT 0,run_epoch INTEGER NOT NULL DEFAULT 0,phase TEXT NOT NULL DEFAULT 'scoping',active_run_id TEXT,active_plan_id TEXT,pending_input_json TEXT,completion_json TEXT,scope_questions INTEGER NOT NULL DEFAULT 0,notification_mode TEXT NOT NULL DEFAULT 'unconfigured',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS project_creation_receipts (owner_id TEXT NOT NULL,client_operation_id TEXT NOT NULL,payload_hash TEXT NOT NULL,project_id TEXT NOT NULL,response_json TEXT NOT NULL,PRIMARY KEY(owner_id,client_operation_id),FOREIGN KEY(project_id) REFERENCES projects(id));
CREATE TABLE IF NOT EXISTS project_constraints (project_id TEXT NOT NULL,id TEXT NOT NULL,goal_version INTEGER NOT NULL,kind TEXT NOT NULL,raw_text TEXT NOT NULL,value_json TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(project_id,id),FOREIGN KEY(project_id) REFERENCES projects(id));
CREATE TABLE IF NOT EXISTS messages (project_id TEXT NOT NULL,id TEXT NOT NULL,seq INTEGER NOT NULL,sender_role TEXT NOT NULL,body TEXT NOT NULL,run_id TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(project_id,id),UNIQUE(project_id,seq),FOREIGN KEY(project_id) REFERENCES projects(id));
CREATE TABLE IF NOT EXISTS artifacts (project_id TEXT NOT NULL,id TEXT NOT NULL,kind TEXT NOT NULL,version INTEGER NOT NULL,content TEXT NOT NULL,evidence_message_ids TEXT NOT NULL DEFAULT '[]',created_by TEXT NOT NULL,supersedes_id TEXT,tombstone INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(project_id,id),UNIQUE(project_id,kind,version),FOREIGN KEY(project_id,supersedes_id) REFERENCES artifacts(project_id,id),FOREIGN KEY(project_id) REFERENCES projects(id));
CREATE TABLE IF NOT EXISTS sources (project_id TEXT NOT NULL,id TEXT NOT NULL,goal_version INTEGER NOT NULL DEFAULT 1,reference_no TEXT NOT NULL,layer TEXT NOT NULL,title TEXT NOT NULL,url TEXT NOT NULL,fetched_at TEXT NOT NULL,status TEXT NOT NULL,verification_status TEXT NOT NULL,summary TEXT NOT NULL DEFAULT '',citations_json TEXT NOT NULL DEFAULT '[]',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(project_id,id),FOREIGN KEY(project_id) REFERENCES projects(id));
CREATE TABLE IF NOT EXISTS assessment_policies (project_id TEXT NOT NULL,id TEXT NOT NULL,version INTEGER NOT NULL,status TEXT NOT NULL,policy_json TEXT NOT NULL,confirmed_message_id TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(project_id,id),UNIQUE(project_id,version),FOREIGN KEY(project_id,confirmed_message_id) REFERENCES messages(project_id,id),FOREIGN KEY(project_id) REFERENCES projects(id));
CREATE TABLE IF NOT EXISTS assessment_sessions (project_id TEXT NOT NULL,id TEXT NOT NULL,purpose TEXT NOT NULL,policy_id TEXT,policy_version INTEGER,goal_version INTEGER NOT NULL,status TEXT NOT NULL,question_ids_json TEXT NOT NULL,required_skills_json TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(project_id,id),FOREIGN KEY(project_id,policy_id) REFERENCES assessment_policies(project_id,id),FOREIGN KEY(project_id) REFERENCES projects(id));
CREATE TABLE IF NOT EXISTS quiz_questions (project_id TEXT NOT NULL,id TEXT NOT NULL,session_id TEXT NOT NULL,version INTEGER NOT NULL,prompt TEXT NOT NULL,skill_id TEXT NOT NULL,kind TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(project_id,id),FOREIGN KEY(project_id,session_id) REFERENCES assessment_sessions(project_id,id));
CREATE TABLE IF NOT EXISTS question_secrets (project_id TEXT NOT NULL,question_id TEXT NOT NULL,reference_answer TEXT NOT NULL,rubric_json TEXT NOT NULL,explanation TEXT NOT NULL,PRIMARY KEY(project_id,question_id),FOREIGN KEY(project_id,question_id) REFERENCES quiz_questions(project_id,id));
CREATE TABLE IF NOT EXISTS quiz_attempts (project_id TEXT NOT NULL,id TEXT NOT NULL,question_id TEXT NOT NULL,attempt_index INTEGER NOT NULL,answer_message_id TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(project_id,id),UNIQUE(project_id,question_id,attempt_index),FOREIGN KEY(project_id,question_id) REFERENCES quiz_questions(project_id,id),FOREIGN KEY(project_id,answer_message_id) REFERENCES messages(project_id,id));
CREATE TABLE IF NOT EXISTS quiz_evaluations (project_id TEXT NOT NULL,id TEXT NOT NULL,attempt_id TEXT NOT NULL,policy_version INTEGER,verdict TEXT NOT NULL,gap TEXT NOT NULL,feedback TEXT NOT NULL,followup TEXT,reveal_allowed INTEGER NOT NULL DEFAULT 0,supersedes_id TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(project_id,id),FOREIGN KEY(project_id,attempt_id) REFERENCES quiz_attempts(project_id,id),FOREIGN KEY(project_id,supersedes_id) REFERENCES quiz_evaluations(project_id,id));
CREATE TABLE IF NOT EXISTS review_schedule (project_id TEXT NOT NULL,id TEXT NOT NULL,skill_id TEXT NOT NULL,learned_date TEXT NOT NULL,offset_days INTEGER NOT NULL,due_date TEXT NOT NULL,form TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',evidence_id TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(project_id,id),FOREIGN KEY(project_id) REFERENCES projects(id));
CREATE TABLE IF NOT EXISTS plan_proposals (project_id TEXT NOT NULL,id TEXT NOT NULL,version INTEGER NOT NULL,base_plan_version INTEGER NOT NULL,base_goal_version INTEGER NOT NULL,changes_json TEXT NOT NULL,impact TEXT NOT NULL,summary TEXT NOT NULL,status TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(project_id,id),FOREIGN KEY(project_id) REFERENCES projects(id));
CREATE TABLE IF NOT EXISTS decisions (project_id TEXT NOT NULL,id TEXT NOT NULL,proposal_id TEXT NOT NULL,proposal_version INTEGER NOT NULL,decision TEXT NOT NULL,message_id TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(project_id,id),FOREIGN KEY(project_id,proposal_id) REFERENCES plan_proposals(project_id,id),FOREIGN KEY(project_id,message_id) REFERENCES messages(project_id,id));
CREATE TABLE IF NOT EXISTS agent_runs (project_id TEXT NOT NULL,id TEXT NOT NULL,operation_id TEXT NOT NULL,epoch INTEGER NOT NULL,status TEXT NOT NULL,command_json TEXT NOT NULL,error_code TEXT,budget_json TEXT NOT NULL DEFAULT '{"model":0,"tool":0,"handoff":0}',retry_count INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(project_id,id),FOREIGN KEY(project_id) REFERENCES projects(id));
CREATE TABLE IF NOT EXISTS command_receipts (project_id TEXT NOT NULL,client_operation_id TEXT NOT NULL,payload_hash TEXT NOT NULL,base_revision INTEGER NOT NULL,run_id TEXT NOT NULL,response_json TEXT NOT NULL,PRIMARY KEY(project_id,client_operation_id),FOREIGN KEY(project_id,run_id) REFERENCES agent_runs(project_id,id));
CREATE TABLE IF NOT EXISTS step_receipts (project_id TEXT NOT NULL,operation_id TEXT NOT NULL,step_key TEXT NOT NULL,epoch INTEGER NOT NULL,base_revision INTEGER NOT NULL,result_json TEXT NOT NULL,PRIMARY KEY(project_id,operation_id,step_key),FOREIGN KEY(project_id) REFERENCES projects(id));
CREATE TABLE IF NOT EXISTS run_steps (project_id TEXT NOT NULL,id TEXT NOT NULL,run_id TEXT NOT NULL,step_key TEXT NOT NULL,status TEXT NOT NULL,result_json TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(project_id,id),UNIQUE(project_id,run_id,step_key),FOREIGN KEY(project_id,run_id) REFERENCES agent_runs(project_id,id));
CREATE TABLE IF NOT EXISTS domain_events (project_id TEXT NOT NULL,seq INTEGER NOT NULL,type TEXT NOT NULL,payload_json TEXT NOT NULL,run_id TEXT,role TEXT,occurred_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(project_id,seq),FOREIGN KEY(project_id) REFERENCES projects(id));
CREATE TABLE IF NOT EXISTS provider_calls (project_id TEXT NOT NULL,id TEXT NOT NULL,run_id TEXT NOT NULL,request_hash TEXT NOT NULL,status TEXT NOT NULL,result_json TEXT,usage_json TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(project_id,id),FOREIGN KEY(project_id,run_id) REFERENCES agent_runs(project_id,id));
CREATE TRIGGER IF NOT EXISTS command_guard BEFORE INSERT ON command_receipts BEGIN SELECT CASE WHEN (SELECT revision FROM projects WHERE id=NEW.project_id) != NEW.base_revision THEN RAISE(ABORT,'REVISION_CONFLICT') END; END;
CREATE TRIGGER IF NOT EXISTS step_guard BEFORE INSERT ON step_receipts BEGIN SELECT CASE WHEN (SELECT run_epoch FROM projects WHERE id=NEW.project_id) != NEW.epoch THEN RAISE(ABORT,'STALE_EPOCH') END; SELECT CASE WHEN (SELECT revision FROM projects WHERE id=NEW.project_id) != NEW.base_revision THEN RAISE(ABORT,'REVISION_CONFLICT') END; END;
CREATE INDEX IF NOT EXISTS projects_owner ON projects(owner_id);
CREATE INDEX IF NOT EXISTS artifacts_kind ON artifacts(project_id,kind,version);
CREATE INDEX IF NOT EXISTS reviews_due ON review_schedule(project_id,due_date,status);
CREATE INDEX IF NOT EXISTS runs_status ON agent_runs(project_id,status);
CREATE TRIGGER IF NOT EXISTS immutable_messages_update BEFORE UPDATE ON messages BEGIN SELECT RAISE(ABORT,'IMMUTABLE_RECORD'); END;
CREATE TRIGGER IF NOT EXISTS immutable_messages_delete BEFORE DELETE ON messages BEGIN SELECT RAISE(ABORT,'IMMUTABLE_RECORD'); END;
CREATE TRIGGER IF NOT EXISTS immutable_artifacts_update BEFORE UPDATE ON artifacts BEGIN SELECT RAISE(ABORT,'IMMUTABLE_RECORD'); END;
CREATE TRIGGER IF NOT EXISTS immutable_artifacts_delete BEFORE DELETE ON artifacts BEGIN SELECT RAISE(ABORT,'IMMUTABLE_RECORD'); END;
CREATE TRIGGER IF NOT EXISTS immutable_quiz_attempts_update BEFORE UPDATE ON quiz_attempts BEGIN SELECT RAISE(ABORT,'IMMUTABLE_RECORD'); END;
CREATE TRIGGER IF NOT EXISTS immutable_quiz_attempts_delete BEFORE DELETE ON quiz_attempts BEGIN SELECT RAISE(ABORT,'IMMUTABLE_RECORD'); END;
CREATE TRIGGER IF NOT EXISTS immutable_quiz_evaluations_update BEFORE UPDATE ON quiz_evaluations BEGIN SELECT RAISE(ABORT,'IMMUTABLE_RECORD'); END;
CREATE TRIGGER IF NOT EXISTS immutable_quiz_evaluations_delete BEFORE DELETE ON quiz_evaluations BEGIN SELECT RAISE(ABORT,'IMMUTABLE_RECORD'); END;
CREATE TRIGGER IF NOT EXISTS immutable_domain_events_update BEFORE UPDATE ON domain_events BEGIN SELECT RAISE(ABORT,'IMMUTABLE_RECORD'); END;
CREATE TRIGGER IF NOT EXISTS immutable_domain_events_delete BEFORE DELETE ON domain_events BEGIN SELECT RAISE(ABORT,'IMMUTABLE_RECORD'); END;
CREATE TRIGGER IF NOT EXISTS immutable_decisions_update BEFORE UPDATE ON decisions BEGIN SELECT RAISE(ABORT,'IMMUTABLE_RECORD'); END;
CREATE TRIGGER IF NOT EXISTS immutable_decisions_delete BEFORE DELETE ON decisions BEGIN SELECT RAISE(ABORT,'IMMUTABLE_RECORD'); END;
CREATE TRIGGER IF NOT EXISTS immutable_command_receipts_update BEFORE UPDATE ON command_receipts BEGIN SELECT RAISE(ABORT,'IMMUTABLE_RECORD'); END;
CREATE TRIGGER IF NOT EXISTS immutable_command_receipts_delete BEFORE DELETE ON command_receipts BEGIN SELECT RAISE(ABORT,'IMMUTABLE_RECORD'); END;
CREATE TRIGGER IF NOT EXISTS immutable_step_receipts_update BEFORE UPDATE ON step_receipts BEGIN SELECT RAISE(ABORT,'IMMUTABLE_RECORD'); END;
CREATE TRIGGER IF NOT EXISTS immutable_step_receipts_delete BEFORE DELETE ON step_receipts BEGIN SELECT RAISE(ABORT,'IMMUTABLE_RECORD'); END;
CREATE TRIGGER IF NOT EXISTS immutable_project_constraints_update BEFORE UPDATE ON project_constraints BEGIN SELECT RAISE(ABORT,'IMMUTABLE_RECORD'); END;
CREATE TRIGGER IF NOT EXISTS immutable_project_constraints_delete BEFORE DELETE ON project_constraints BEGIN SELECT RAISE(ABORT,'IMMUTABLE_RECORD'); END;
CREATE TRIGGER IF NOT EXISTS immutable_question_secrets_update BEFORE UPDATE ON question_secrets BEGIN SELECT RAISE(ABORT,'IMMUTABLE_RECORD'); END;
CREATE TRIGGER IF NOT EXISTS immutable_question_secrets_delete BEFORE DELETE ON question_secrets BEGIN SELECT RAISE(ABORT,'IMMUTABLE_RECORD'); END;
CREATE TRIGGER IF NOT EXISTS confirmed_policy_update BEFORE UPDATE ON assessment_policies WHEN OLD.status='confirmed' BEGIN SELECT RAISE(ABORT,'IMMUTABLE_POLICY'); END;
CREATE TRIGGER IF NOT EXISTS confirmed_policy_delete BEFORE DELETE ON assessment_policies WHEN OLD.status='confirmed' BEGIN SELECT RAISE(ABORT,'IMMUTABLE_POLICY'); END;
